// lunae · Nowe zamówienia → Discord — classify recently modified orders into notification events.
// Events: new (processing/completed/on-hold, paid or created within WINDOW), failed, pending60 (unpaid > 60 min).
// Never outputs customer names, emails, phones or street addresses.
const ADMIN_URL = 'https://lunae.pl/wp-admin/admin.php?page=wc-orders&action=edit&id=';
const WINDOW_MS = 2 * 60 * 60 * 1000;      // only orders paid/created in the last 2 h count as "new" (no history spam)
const PENDING_MS = 60 * 60 * 1000;         // pending longer than this -> "porzucona płatność?"
const MAX_AGE_MS = 24 * 60 * 60 * 1000;    // ignore failed/pending orders older than 24 h
const PAID_LIKE = ['processing', 'completed', 'on-hold'];
const now = Date.now();

function gmt(s) {
  if (!s) return null;
  const str = String(s);
  const v = Date.parse(/Z$|[+-]\d\d:\d\d$/.test(str) ? str : str + 'Z');
  return isNaN(v) ? null : v;
}
function money(v, currency) {
  const n = Number(v) || 0;
  const parts = Math.abs(n).toFixed(2).split('.');
  const intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
  const cur = !currency || currency === 'PLN' ? 'zł' : currency;
  return (n < 0 ? '-' : '') + intPart + ',' + parts[1] + ' ' + cur;
}
function clip(s, max) {
  s = String(s == null ? '' : s).trim();
  if (!s) return '—';
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
}
function itemLine(li) {
  let name = String(li.name || 'Produkt').trim();
  const extras = [];
  for (const m of (li.meta_data || [])) {
    if (!m || typeof m.key !== 'string' || m.key.charAt(0) === '_') continue;
    const raw = m.display_value != null ? m.display_value : m.value;
    if (typeof raw !== 'string' && typeof raw !== 'number') continue;
    const clean = String(raw).replace(/<[^>]*>/g, '').trim();
    if (clean && clean.length <= 40 && name.indexOf(clean) === -1) extras.push(clean);
  }
  if (extras.length) name += ' – ' + extras.join(', ');
  return '• ' + name + ' × ' + (Number(li.quantity) || 1);
}
function metaVal(o, key) {
  const m = (o.meta_data || []).find(function (x) { return x && x.key === key; });
  return m ? m.value : undefined;
}

const out = [];
const seen = {};
for (const item of $input.all()) {
  const o = item.json || {};
  if (!o.id || !o.status || seen[o.id]) continue;
  seen[o.id] = true;

  const created = gmt(o.date_created_gmt);
  const paid = gmt(o.date_paid_gmt);
  let event = null;
  let eventTime = null;
  if (PAID_LIKE.indexOf(o.status) !== -1) {
    eventTime = paid || created;
    if (eventTime && now - eventTime <= WINDOW_MS) event = 'new';
  } else if (o.status === 'failed') {
    eventTime = gmt(o.date_modified_gmt) || created;
    if (created && now - created <= MAX_AGE_MS) event = 'failed';
  } else if (o.status === 'pending') {
    eventTime = created;
    if (created && now - created >= PENDING_MS && now - created <= MAX_AGE_MS) event = 'pending60';
  }
  if (!event) continue;

  const number = o.number || o.id;
  const total = money(o.total, o.currency);
  const lines = (o.line_items || []).map(itemLine);
  let itemsText = lines.slice(0, 15).join('\n');
  if (lines.length > 15) itemsText += '\n… i ' + (lines.length - 15) + ' więcej';
  if (!itemsText) itemsText = '—';

  const ship = (o.shipping_lines || []).map(function (s) {
    const cost = (Number(s.total) || 0) + (Number(s.total_tax) || 0);
    return (s.method_title || 'Dostawa') + (cost > 0 ? ' (' + money(cost, o.currency) + ')' : ' (darmowa)');
  }).join(', ');
  const city = (o.shipping && o.shipping.city) || (o.billing && o.billing.city) || '';
  const payment = o.payment_method_title || o.payment_method || '';
  const invoiceAsk = metaVal(o, '_billing_invoice_ask');
  const wantsInvoice = invoiceAsk === 'yes' || invoiceAsk === '1' || invoiceAsk === true || invoiceAsk === 1;
  const link = ADMIN_URL + o.id;

  let content, title, color, footer;
  const fields = [
    { name: 'Kwota', value: total, inline: true },
    { name: 'Płatność', value: clip(payment, 100), inline: true },
  ];
  if (event === 'new') {
    const onHold = o.status === 'on-hold';
    content = (onHold ? '⏸️ Nowe zamówienie (czeka na wpłatę) #' : '🛍️ Nowe zamówienie #') + number + ' · ' + total;
    title = 'Zamówienie #' + number + (onHold ? ' · czeka na wpłatę' : ' · opłacone');
    color = onHold ? 0xF1C40F : 0x2ECC71;
    fields.push({ name: 'Dostawa', value: clip(ship, 200), inline: true });
    fields.push({ name: 'Miasto', value: clip(city, 60), inline: true });
    if (wantsInvoice) fields.push({ name: 'Faktura', value: 'na firmę (prośba o FV)', inline: true });
    footer = 'Status: ' + o.status;
  } else if (event === 'failed') {
    content = '⚠️ Nieudana płatność · #' + number + ' · ' + total;
    title = 'Nieudana płatność #' + number;
    color = 0xE74C3C;
    fields.push({ name: 'Miasto', value: clip(city, 60), inline: true });
    footer = 'Status: failed · klient może ponowić płatność';
  } else {
    const mins = Math.round((now - created) / 60000);
    content = '⏳ Porzucona płatność? #' + number + ' · ' + total + ' · nieopłacone od ' + mins + ' min';
    title = 'Nieopłacone zamówienie #' + number;
    color = 0x95A5A6;
    fields.push({ name: 'Miasto', value: clip(city, 60), inline: true });
    footer = 'Status: pending > 60 min · jednorazowe powiadomienie';
  }

  const embed = {
    title: title,
    url: link,
    color: color,
    description: itemsText,
    fields: fields,
    footer: { text: footer },
    timestamp: new Date(eventTime || now).toISOString(),
  };

  out.push({
    json: {
      order_key: o.id + ':' + event,
      order_id: o.id,
      event: event,
      status: o.status,
      content: content.slice(0, 1900),
      embed_json: JSON.stringify(embed),
    },
  });
}
return out;
